"""Actual Monaco navigation/review, Git index operations and test retry in isolation."""
import json,os,subprocess,sys,tempfile,threading,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from backend.runtime_paths import find_tool
from playwright.sync_api import sync_playwright,expect

def main():
 out=ROOT/'qa-output/editor-depth-ui';out.mkdir(exist_ok=True);checks=[];errors=[]
 with tempfile.TemporaryDirectory(prefix='zenit-editor-depth-ui-') as temporary:
  base=Path(temporary);root=base/'project';root.mkdir();main_source='from helper import value\nprint(value)\n'
  sources={'main.py':main_source,'helper.py':'value = 7\n','changed.txt':'old\n','calc.py':'VALUE=7\n','tests/test_calc.py':'import unittest\nfrom calc import VALUE\nclass Cases(unittest.TestCase):\n def test_ok(self): self.assertEqual(VALUE,7)\n def test_bad(self): self.assertEqual(VALUE,8)\n'}
  for path,text in sources.items():file=root/path;file.parent.mkdir(parents=True,exist_ok=True);file.write_text(text,'utf-8',newline='')
  def git(*args):
   result=subprocess.run([find_tool('git'),'-c','core.hooksPath='+os.devnull,*args],cwd=root,capture_output=True,timeout=15);assert not result.returncode,result.stderr;return result.stdout
  git('init','-q');git('config','user.name','Fixture');git('config','user.email','fixture@example.invalid');git('config','core.autocrlf','false');git('add','-A');git('commit','-qm','fixture')
  app=Application(ROOT,root,data_dir=base/'profile');f=app.features;app.workspace.trusted=True
  f.prefs.update({'general.locale':'es','general.showWelcome':False,'updates.automatic':False,'editor.autoLanguageServer':False,'files.autoSave':False,'security.confirmRoutineActions':False});f.studio.update({'onboarded':True})
  f.tools.config['servers'].append({'id':'editor-depth-fixture','label':'Protocol fixture','argv':[sys.executable,str(ROOT/'tests/fixtures/lsp_depth.py')],'languages':['python']})
  server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
  try:
   with sync_playwright() as playwright:
    browser=playwright.chromium.launch(channel='msedge',headless=True);page=browser.new_page(viewport={'width':1600,'height':1000});page.on('pageerror',lambda error:errors.append(str(error)));page.on('console',lambda message:print('CONSOLE',message.type,message.text) if message.type in ('error','warning') else None)
    def inject(route):
     response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get editor(){return editor},get platform(){return platformUI},get studio(){return studio},get desktop(){return desktopUI},get depth(){return platformUI.editorDepth},openFile};')
    def settle():page.wait_for_function('()=>!document.querySelector("#modal")?.getAnimations({subtree:true}).some(a=>a.playState==="running"&&a.effect?.getComputedTiming().iterations!==Infinity)')
    page.route('**/src/app.js',inject);page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function('window.lumen?.ready');page.evaluate('__qa.openFile("main.py")');page.evaluate('__qa.platform.startLSP("editor-depth-fixture",true)')
    page.evaluate('()=>{__qa.editor.view.setPosition({lineNumber:2,column:8});__qa.editor.view.trigger("fixture","editor.action.revealDefinition",{});}')
    page.wait_for_function('__qa.editor.current==="helper.py"');page.evaluate('__qa.depth.move(-1)');page.wait_for_function('__qa.editor.current==="main.py"');assert page.evaluate('__qa.editor.view.getPosition().column')==8
    page.evaluate('__qa.depth.move(1)');page.wait_for_function('__qa.editor.current==="helper.py"');checks.append('Native LSP definition crosses files and exact cursor history supports back and forward on Windows URI case variants')
    page.evaluate('__qa.openFile("main.py")');page.evaluate('()=>{__qa.editor.view.focus();__qa.editor.view.setPosition({lineNumber:2,column:8});void __qa.editor.view.getAction("editor.action.rename").run();}')
    rename=page.locator('.rename-box input');rename.wait_for(state='visible');expect(rename).to_be_focused();rename.fill('count');expect(rename).to_have_value('count');rename.press('Enter')
    expect(page.locator('.editor-change-review')).to_be_visible(timeout=15000);expect(page.locator('.editor-change-list')).to_contain_text('helper.py');settle();page.screenshot(path=str(out/'rename-review-day.png'));page.locator('[data-review-apply]').click()
    page.wait_for_function('__qa.editor.models.get("helper.py").model.getValue().includes("count =")');assert 'print(count)' in page.evaluate('__qa.editor.models.get("main.py").model.getValue()');assert (root/'main.py').read_text()==main_source
    page.evaluate('__qa.editor.view.focus()');page.keyboard.press('Control+z');page.wait_for_function('__qa.editor.models.get("main.py").model.getValue().includes("print(value)")');assert page.evaluate('__qa.editor.models.get("helper.py").model.getValue()')==sources['helper.py']
    page.keyboard.press('Control+Shift+z');page.wait_for_function('__qa.editor.models.get("helper.py").model.getValue().includes("count =")');assert 'print(count)' in page.evaluate('__qa.editor.models.get("main.py").model.getValue()');page.keyboard.press('Control+z');page.wait_for_function('__qa.editor.models.get("main.py").model.getValue().includes("print(value)")');checks.append('F2 native LSP rename previews both files; Ctrl+Z and Ctrl+Shift+Z restore and reapply the set without saving source files')
    # Restore the fixture models for subsequent independent checks.
    page.evaluate('(sources)=>{for(const [path,text] of Object.entries(sources)){const r=__qa.editor.models.get(path);if(r?.model)r.model.setValue(text);}}',sources)
    page.evaluate('__qa.depth.capabilities()');expect(page.locator('.language-depth-report')).to_contain_text('Renombrado');expect(page.locator('.language-depth-report')).to_contain_text('Referencias');settle();page.screenshot(path=str(out/'language-capabilities.png'));page.locator('[data-depth-symbols]').click();page.locator('.quick-input-widget').wait_for(state='visible');expect(page.locator('.quick-input-widget')).to_contain_text('main');page.locator('.modal-motion-snapshot').wait_for(state='detached');page.wait_for_function('()=>!document.getAnimations().some(a=>a.playState==="running"&&a.effect?.getComputedTiming().iterations!==Infinity)');bounds=page.evaluate('()=>{const widget=document.querySelector(".quick-input-widget").getBoundingClientRect(),editor=__qa.editor.view.getDomNode().getBoundingClientRect();return {widget:widget.toJSON(),editor:editor.toJSON()}}');assert bounds['widget']['left']>=bounds['editor']['left'] and bounds['widget']['right']<=bounds['editor']['right']+1,bounds;assert bounds['widget']['width']>=min(300,bounds['editor']['width']-24),bounds;print('OUTLINE BOUNDS',json.dumps(bounds));page.screenshot(path=str(out/'outline-geometry-day.png'));page.keyboard.press('Escape');checks.append('Language report Symbols button restores focus and the outline fits inside the editor without clipping')
    page.evaluate('__qa.editor.view.focus()');page.keyboard.press('Control+Shift+o');page.locator('.quick-input-widget').wait_for(state='visible');expect(page.locator('.quick-input-widget')).to_contain_text('main');page.keyboard.press('Escape');checks.append('Ctrl+Shift+O opens the actual native LSP outline instead of Save As')
    page.evaluate('()=>{__qa.editor.view.focus();__qa.editor.view.trigger("fixture","zenit.contextMenu",{});}');expect(page.locator('.editor-context-menu').first).to_contain_text('Ir a definición');expect(page.locator('.editor-context-menu').first).to_contain_text('Buscar referencias');page.keyboard.press('Escape');checks.append('Context menu exposes active navigation commands even when Monaco has no action wrapper')
    page.evaluate('()=>{__qa.editor.view.focus();void __qa.editor.view.getAction("editor.action.refactor").run();}');page.get_by_text('Fixture · cambiar literal',exact=True).click();expect(page.locator('.editor-change-review')).to_be_visible();page.locator('[data-review-apply]').click();page.wait_for_function('__qa.editor.models.get("helper.py").model.getValue().includes("= 8")');page.evaluate('__qa.depth.edits.undo()');assert page.evaluate('__qa.editor.models.get("helper.py").model.getValue()')==sources['helper.py'];checks.append('A native LSP refactoring action is reviewed and the complete edit set can be restored')
    page.evaluate('()=>{__qa.editor.view.setPosition({lineNumber:2,column:8});__qa.editor.view.focus();__qa.editor.view.trigger("fixture","editor.action.goToReferences",{});}');page.locator('.reference-zone-widget').wait_for(state='visible');page.keyboard.press('Escape');checks.append('Native LSP references open the actual editor reference view')
    # Search and replacement include a draft, not just disk contents.
    page.evaluate('__qa.editor.insertText("from helper import value\\nprint(value + 1)\\n",true)');page.evaluate('__qa.studio.search()');page.locator('#studio-search').fill('value');page.wait_for_function('document.querySelector("#studio-search-results").textContent.includes("+ 1")');checks.append('Project search finds the current unsaved buffer')
    page.evaluate('__qa.editor.view.setPosition({lineNumber:1,column:1})');page.get_by_role('button',name='main.py, línea 2',exact=True).click();page.wait_for_function('__qa.editor.view.getPosition().lineNumber===2');page.evaluate('__qa.depth.move(-1)');assert page.evaluate('__qa.editor.view.getPosition().lineNumber')==1;assert page.evaluate('__qa.editor.view.getPosition().column')==1;page.evaluate('__qa.studio.search()');page.wait_for_function('document.querySelector("#studio-search-results").textContent.includes("+ 1")');checks.append('Search jumps within the same file retain the original cursor for Back')
    page.locator('[data-search-show-replace]').click();page.locator('[data-search-replacement]').fill('count');page.locator('[data-search-review-replace]').click();expect(page.locator('.editor-change-review')).to_be_visible();page.locator('[data-review-apply]').click()
    page.wait_for_function('__qa.editor.models.get("helper.py").model.getValue().includes("count =")');page.evaluate('__qa.depth.edits.undo()');assert 'value + 1' in page.evaluate('__qa.editor.models.get("main.py").model.getValue()');assert page.evaluate('__qa.editor.models.get("helper.py").model.getValue()')==sources['helper.py'];assert (root/'main.py').read_text()==main_source;checks.append('Reviewed project replacement spans files and restoring the set preserves an earlier unsaved draft')
    # A concurrent edit must block the whole review before it changes anything.
    page.evaluate('__qa.platform.closePage()');page.evaluate('()=>{void __qa.depth.edits.apply([{path:"main.py",before:__qa.editor.models.get("main.py").model.getValue(),after:"replacement",revision:__qa.editor.models.get("main.py").revision}]);}')
    expect(page.locator('.editor-change-review')).to_be_visible();page.evaluate('__qa.editor.models.get("main.py").model.setValue("concurrent draft")');page.locator('[data-review-apply]').click();expect(page.locator('.editor-change-status')).to_contain_text('cambió');page.locator('[data-review-cancel]').click();assert page.evaluate('__qa.editor.models.get("main.py").model.getValue()')=='concurrent draft';checks.append('Concurrent buffer changes invalidate an entire pending replacement review')
    page.evaluate('(sources)=>{for(const [path,text] of Object.entries(sources)){const r=__qa.editor.models.get(path);if(r?.model)r.model.setValue(text);}}',sources)
    (root/'changed.txt').write_text('new\n','utf-8',newline='');page.locator('.rail-item[data-view=git]').click();page.locator('[data-git-path="changed.txt"][data-git-scope=working]').wait_for();page.locator('[data-git-path="changed.txt"][data-git-scope=working]').click();expect(page.locator('.git-change-review')).to_be_visible();settle();page.screenshot(path=str(out/'git-review-day.png'));page.locator('[data-git-apply]').click();page.locator('[data-git-path="changed.txt"][data-git-scope=staged]').wait_for();assert git('show',':changed.txt')==b'new\n'
    page.locator('[data-git-path="changed.txt"][data-git-scope=staged]').click();page.locator('[data-git-apply]').click();page.locator('[data-git-path="changed.txt"][data-git-scope=working]').wait_for();assert git('show',':changed.txt')==b'old\n';assert (root/'changed.txt').read_text()=='new\n';checks.append('Git sidebar reviews real diffs and stages/unstages the real index without touching working bytes')
    page.evaluate('()=>{const p=__qa.platform,api=p.api.bind(p);window.__gitAPI=api;p.api=(path,...args)=>path==="/git/changes"?new Promise(resolve=>{window.__releaseGit=async()=>resolve(await api(path,...args));}):api(path,...args);document.querySelector(".rail-item[data-view=git]").click();document.querySelector(".rail-item[data-view=explorer]").click();}')
    page.evaluate('__releaseGit()');page.evaluate('()=>{__qa.platform.api=__gitAPI;}');assert page.locator('#sidebar-content .git-workspace').count()==0;checks.append('A late Git response cannot replace the explorer after navigating away')
    page.evaluate('__qa.platform.testsUI.open()');page.locator('.test-run-form button[type=submit]').click();expect(page.locator('.test-saved-sources')).to_contain_text('archivos guardados');page.locator('[data-tests-confirm]').click();page.locator('[data-tests-failed]').wait_for(timeout=30000);page.locator('[data-tests-failed]').click();expect(page.locator('.test-command-review')).to_contain_text('test_bad');expect(page.locator('.test-command-review')).not_to_contain_text('test_ok');page.locator('[data-tests-confirm]').click();page.wait_for_function('document.querySelectorAll(".test-result-row").length===1');expect(page.locator('.test-result-row')).to_contain_text('test_bad');checks.append('Test explorer previews and reruns only the failed unittest case with actual result rows')
    (root/'calc.py').write_text('VALUE=8\n','utf-8',newline='');page.locator('.test-results-stale').wait_for(timeout=10000);expect(page.locator('.test-results-stale')).to_contain_text('calc.py');checks.append('A dependency changed after testing marks the old report stale')
    page.evaluate('__qa.platform.closePage()');page.evaluate('__qa.depth.capabilities()');page.evaluate('__qa.platform.savePreference("appearance.theme","dark")');settle();page.screenshot(path=str(out/'language-capabilities-dark.png'));page.set_viewport_size({'width':640,'height':720});settle();rect=page.locator('.language-depth-report').bounding_box();assert rect['x']>=0 and rect['x']+rect['width']<=641,rect;page.screenshot(path=str(out/'language-capabilities-640.png'));checks.append('Capability review fits both themes and a 640 px viewport')
    assert not errors,errors;browser.close()
  finally:server.shutdown();server.server_close();f.shutdown();app.runner.shutdown()
 (out/'verification.json').write_text(json.dumps({'checks':checks,'errors':errors},ensure_ascii=False,indent=2),'utf-8');print(json.dumps({'passed':len(checks),'errors':errors}))

if __name__=='__main__':main()
